<script>
    const dialog = document.querySelector('#figure-dialog');
    for (const link of document.querySelectorAll('.figure-link')) {
        link.addEventListener('click', event => {
            if (!dialog.showModal || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
            event.preventDefault();
            const target = dialog.querySelector('img');
            target.src = link.href;
            target.alt = link.querySelector('img').alt;
            const holder = target.parentElement;
            holder.querySelector('.marker-annotation')?.remove();
            const marker = link.querySelector('.marker-annotation');
            holder.classList.toggle('marker-figure', !!marker);
            if (marker) holder.append(marker.cloneNode(true));
            dialog.showModal();
        });
    }
    dialog.addEventListener('click', event => {
        if (event.target === dialog) dialog.close();
    });
</script>
